# Let me check the JSON files for any exchange rate data
import json
import os

for filename in os.listdir('/app/resources'):
    if filename.endswith('.json'):
        try:
            with open(f'/app/resources/{filename}', 'r') as f:
                data = json.load(f)
                # Search for any exchange rate data in the JSON
                json_str = json.dumps(data)
                if 'exchange' in json_str.lower() or 'rate' in json_str.lower():
                    print(f"{filename}: Contains exchange/rate data")
                    # Find the key
                    if isinstance(data, dict):
                        for key in data.keys():
                            if 'exchange' in key.lower() or 'rate' in key.lower():
                                print(f"  Key: {key}")
        except Exception as e:
            print(f"Error in {filename}: {e}")
