import json
import os

# Check main json files
for filename in ['treasury_bulletin_1960_01.json', 'treasury_bulletin_1960_02.json']:
    try:
        with open(f'/app/resources/{filename}', 'r') as f:
            data = json.load(f)

        # Check if it's a dict and look at top-level keys
        if isinstance(data, dict):
            print(f"\n{filename} keys: {list(data.keys())[:20]}")

            # Check if there might be exchange rate data nested somewhere
            def search_dict(d, path=""):
                if isinstance(d, dict):
                    for key, value in d.items():
                        if 'exchang' in key.lower() or 'rate' in key.lower():
                            print(f"  Found: {path}/{key}")
                        if isinstance(value, dict):
                            search_dict(value, f"{path}/{key}")
                elif isinstance(d, list) and len(d) > 0 and isinstance(d[0], dict):
                    for item in d[:3]:  # Just check first few
                        search_dict(item, path)

            search_dict(data)
    except Exception as e:
        print(f"Error in {filename}: {e}")
